import asyncio
import datetime
import os
import sys
import uuid
from dataclasses import dataclass
from typing import Any, List, Optional

from dotenv import load_dotenv
from pydantic import BaseModel, Field

# Allow asyncio.run inside Kaggle/Jupyter notebooks
try:
    import nest_asyncio

    nest_asyncio.apply()
except ImportError:
    pass

try:
    from google.adk.agents.llm_agent import LlmAgent
    from google.adk.runners import Runner
    from google.adk.sessions.session import Session
    from google.adk.sessions.in_memory_session_service import InMemorySessionService
    from google.adk.memory.in_memory_memory_service import InMemoryMemoryService
    from google.adk.tools.load_memory_tool import LoadMemoryTool
    from google.adk.events.event import Event
    from google.genai import types
except ImportError as e:
    print(f"CRITICAL ERROR: Failed to import ADK modules: {e}")
    print("Please ensure google-adk is installed in the current environment.")
    sys.exit(1)

load_dotenv()

# Configure Gemini API Key
try:
    from kaggle_secrets import UserSecretsClient
    user_secrets = UserSecretsClient()
    kaggle_api_key = user_secrets.get_secret("GOOGLE_API_KEY")
    if kaggle_api_key:
        os.environ["GOOGLE_API_KEY"] = kaggle_api_key
        print("Successfully loaded GOOGLE_API_KEY from Kaggle Secrets.")
except ImportError:
    pass
except Exception as e:
    print(f"Note: Could not load from Kaggle Secrets: {e}")

# Fallback for local execution (keeps demo runnable without secrets)
if not os.getenv("GOOGLE_API_KEY"):
    print("WARNING: GOOGLE_API_KEY not found. Using dummy key; real calls will fail.")
    os.environ["GOOGLE_API_KEY"] = "dummy_key_for_demo"

# =============================================================================
# 1. SETUP & CONFIGURATION
# =============================================================================

APP_NAME = "Memoria"
USER_ID = "user_001"
SESSION_ID_RETRIEVAL = "retrieval_session"

# Model Constants
# ADK resolves model names strings to BaseLlm. 
# We use standard Gemini names.
FAST_MODEL_NAME = "gemini-2.5-flash-lite"
MODEL_NAME = "gemini-2.5-flash-lite"

# Shared Services
# These services act as the "Bus" connecting all agents
session_service = InMemorySessionService()
memory_service = InMemoryMemoryService()

# =============================================================================
# 2. DATA MODELS (EDGE LAYER)
# =============================================================================

@dataclass
class StreamEvent:
    """Mock Input Stream Event."""
    timestamp: datetime.datetime
    source: str
    content: str
    
    def to_prompt(self) -> str:
        return f"[{self.timestamp.strftime('%H:%M')}] [{self.source}]: {self.content}"

# Pydantic Models for Agent Structured Output
class StateOutput(BaseModel):
    state: List[str] = Field(description="Current active states, e.g., ['Commuting', 'Driving']")

class FactOutput(BaseModel):
    fact: Optional[str] = Field(description="Extracted atomic fact, or null if none")
    tags: Optional[List[str]] = Field(description="Tags for the fact")

class TriggerOutput(BaseModel):
    is_trigger: bool = Field(description="True if proactive help is needed")
    reason: Optional[str] = Field(description="Why trigger was activated")

class MemoriaLlmAgent(LlmAgent):
    """Subclass to help ADK infer the correct app origin."""
    pass

# =============================================================================
# 3. AGENT DEFINITIONS
# =============================================================================

# Level 0: Working Memory (State Machine)
working_memory_agent = MemoriaLlmAgent(
    name="WorkingMemory",
    model=MODEL_NAME,
    instruction="""
    You are a state machine tracker. Analyze the incoming event stream and determine the current user activity/state.
    Possible states: Commuting, Driving, Work Meeting, Socializing, Home, Unpacking, Idle, Shopping, etc.
    Maintain continuity but detect changes.
    """,
    output_schema=StateOutput,
    output_key="state_output"
)

# Intent Router (Reflex)
intent_router = MemoriaLlmAgent(
    name="IntentRouter",
    model=FAST_MODEL_NAME,
    instruction="""
    Analyze the event. Does it require a proactive suggestion or reminder?
    Triggers: Questions about missing items, forgotten tasks, safety risks.
    """,
    output_schema=TriggerOutput,
    output_key="trigger_output"
)

# Suggestion Agent (Concierge)
suggestion_agent = MemoriaLlmAgent(
    name="SuggestionAgent",
    model=MODEL_NAME,
    instruction="""
    You are a helpful concierge. Based on the user's situation and memory, provide a short, helpful nudge or suggestion.
    Context: User just asked about milk.
    Memory Fact: User threw away empty oat milk yesterday.
    """,
)

# Episodic Agent (Biographer)
episodic_agent = MemoriaLlmAgent(
    name="EpisodicAgent",
    model=MODEL_NAME,
    instruction="""
    Summarize the provided list of events into a concise narrative journal entry.
    Include times, people, locations, and key decisions.
    """,
)

# Fact Manager (Librarian)
fact_manager = MemoriaLlmAgent(
    name="FactManager",
    model=MODEL_NAME,
    instruction="""
    Extract ONE atomic fact from the text if it contains useful long-term knowledge (preferences, locations, ideas).
    If no useful fact, return null.
    """,
    output_schema=FactOutput,
    output_key="fact_output"
)

# Retrieval Agent (Search Engine)
# Uses the built-in LoadMemoryTool to access the MemoryService
retrieval_agent = MemoriaLlmAgent(
    name="RetrievalAgent",
    model=MODEL_NAME,
    instruction="""
    You are a helpful assistant with access to the user's memory.
    Use 'load_memory' tool to search for answers in the user's past.
    If asked about facts, keys, or past events, SEARCH MEMORY first.
    """,
    tools=[LoadMemoryTool()]
)

# =============================================================================
# 4. MEMORY MANAGEMENT UTILS
# =============================================================================

async def ensure_session(service, app_name, user_id, session_id):
    """Ensures a session exists."""
    session = await service.get_session(app_name=app_name, user_id=user_id, session_id=session_id)
    if not session:
        session = await service.create_session(app_name=app_name, user_id=user_id, session_id=session_id)
    return session

async def add_text_to_memory(text: str, source: str = "system"):
    """
    Inserts text into InMemoryMemoryService.
    Mechanism: Create a temporary session, append event, add session to memory.
    """
    temp_session_id = f"mem_ingest_{uuid.uuid4()}"
    # Use helper to create
    session = await ensure_session(session_service, APP_NAME, USER_ID, temp_session_id)
    
    event = Event(
        invocation_id=str(uuid.uuid4()),
        author=source,
        content=types.Content(parts=[types.Part(text=text)])
    )
    
    await session_service.append_event(session=session, event=event)
    await memory_service.add_session_to_memory(session)

# =============================================================================
# 5. SIMULATION LOOP
# =============================================================================

async def process_stream():
    print("\n" + "="*50)
    print("STARTING MEMORIA SIMULATION (ADK)")
    print("="*50 + "\n")

    # Initialize shared runner for retrieval (to keep session state for user)
    # Ensure retrieval session exists
    await ensure_session(session_service, APP_NAME, USER_ID, SESSION_ID_RETRIEVAL)
    
    retrieval_runner = Runner(
        agent=retrieval_agent,
        app_name=APP_NAME,
        session_service=session_service,
        memory_service=memory_service
    )

    base_time = datetime.datetime.now()
    stream_data = [
        StreamEvent(base_time, "User", "Note to self: We should actually use a graph database for the relationship mapping. It would be way better than a flat vector store."),
        StreamEvent(base_time + datetime.timedelta(minutes=10), "Camera", "User enters cafe. Sits at table. Alex arrives."),
        StreamEvent(base_time + datetime.timedelta(minutes=15), "Camera", "User is sitting opposite 'Alex'. Napkin sketch on table."),
        StreamEvent(base_time + datetime.timedelta(minutes=15, seconds=5), "User", "I'm just stuck on the navigation flow. It feels too rigid."),
        StreamEvent(base_time + datetime.timedelta(minutes=15, seconds=10), "Alex", "Let me see. What if we made it circular? Like... floating here?"),
        StreamEvent(base_time + datetime.timedelta(minutes=15, seconds=15), "Camera", "'Alex' is pointing to the bottom-right corner of the napkin sketch, drawing a circular gesture."),
        StreamEvent(base_time + datetime.timedelta(minutes=15, seconds=20), "User", "Oh, that's actually brilliant. A radial menu?"),
        StreamEvent(base_time + datetime.timedelta(minutes=15, seconds=25), "Alex", "Exactly. It saves screen space."),
        StreamEvent(base_time + datetime.timedelta(minutes=60), "Camera", "User leaves cafe. Enters car."),
        StreamEvent(base_time + datetime.timedelta(minutes=90), "Camera", "User enters living room. User places 'Car Keys' on the 'Bookshelf' next to the green plant."),
        StreamEvent(base_time + datetime.timedelta(minutes=120), "Camera", "User picks up 'Oat Milk' in grocery aisle."),
        StreamEvent(base_time + datetime.timedelta(minutes=120, seconds=5), "User", "Wait, do we have this? I think the one in the fridge is empty."),
    ]

    buffer_events = []
    current_state = ["Idle"]

    for event in stream_data:
        print(f"--- Processing: {event.to_prompt()} ---")
        prompt_text = event.to_prompt()
        buffer_events.append(prompt_text)

        # ----------------------------------------
        # 1. Fact Extraction
        # ----------------------------------------
        try:
            # Ephemeral runner for single-turn extraction
            fact_session_service = InMemorySessionService()
            fact_session_id = f"fact_{uuid.uuid4()}"
            await ensure_session(fact_session_service, APP_NAME, USER_ID, fact_session_id)
            
            fact_runner = Runner(
                agent=fact_manager, 
                app_name=APP_NAME, 
                session_service=fact_session_service # Isolated session
            )
            async for evt in fact_runner.run_async(
                user_id=USER_ID,
                session_id=fact_session_id, 
                new_message=types.Content(parts=[types.Part(text=prompt_text)])
            ):
                # Check for structured output in state_delta
                if evt.actions.state_delta and "fact_output" in evt.actions.state_delta:
                    fact_data = evt.actions.state_delta["fact_output"]
                    # fact_data is a dict because ADK dumps the model
                    if fact_data.get("fact"):
                        fact_str = fact_data["fact"]
                        tags = fact_data.get("tags", [])
                        print(f"  -> [FactDB] Extracted: {fact_str}")
                        await add_text_to_memory(f"Fact: {fact_str} Tags: {tags}", source="FactManager")
        except Exception as e:
            print(f"Fact Error: {e}")

        # ----------------------------------------
        # 2. Working Memory (State Machine)
        # ----------------------------------------
        try:
            wm_session_id = f"wm_{uuid.uuid4()}"
            await ensure_session(session_service, APP_NAME, USER_ID, wm_session_id)
            
            wm_runner = Runner(
                agent=working_memory_agent, 
                app_name=APP_NAME, 
                session_service=session_service
            )
            wm_prompt = f"Current State: {current_state}\nNew Event: {prompt_text}"
            
            async for evt in wm_runner.run_async(
                user_id=USER_ID,
                session_id=wm_session_id,
                new_message=types.Content(parts=[types.Part(text=wm_prompt)])
            ):
                if evt.actions.state_delta and "state_output" in evt.actions.state_delta:
                    state_data = evt.actions.state_delta["state_output"]
                    new_state = state_data.get("state", current_state)
                    
                    if new_state != current_state:
                        print(f"  [WorkingMemory] State Switch: {current_state} -> {new_state}")
                        
                        # 3. Trigger Episodic Agent (Consolidation)
                        print("  >> Triggering EpisodicAgent...")
                        
                        epi_session_id = f"epi_{uuid.uuid4()}"
                        await ensure_session(session_service, APP_NAME, USER_ID, epi_session_id)
                        
                        epi_runner = Runner(agent=episodic_agent, app_name=APP_NAME, session_service=session_service)
                        epi_prompt = f"Activity: {current_state}\nEvents:\n" + "\n".join(buffer_events)
                        
                        summary = None
                        async for epi_evt in epi_runner.run_async(
                            user_id=USER_ID,
                            session_id=epi_session_id,
                            new_message=types.Content(parts=[types.Part(text=epi_prompt)])
                        ):
                            if epi_evt.author == episodic_agent.name and epi_evt.content:
                                summary = epi_evt.content.parts[0].text
                        
                        if summary:
                            print(f"  -> [EpisodicDB] Journal Entry: {summary}")
                            await add_text_to_memory(f"Episode Summary: {summary}", source="EpisodicAgent")
                        
                        buffer_events = [] # Clear buffer
                        
                    current_state = new_state
        except Exception as e:
            print(f"WM Error: {e}")

        # ----------------------------------------
        # 4. Intent Router
        # ----------------------------------------
        try:
            router_session_id = f"router_{uuid.uuid4()}"
            await ensure_session(session_service, APP_NAME, USER_ID, router_session_id)
            
            router_runner = Runner(agent=intent_router, app_name=APP_NAME, session_service=session_service)
            async for evt in router_runner.run_async(
                user_id=USER_ID,
                session_id=router_session_id,
                new_message=types.Content(parts=[types.Part(text=prompt_text)])
            ):
                if evt.actions.state_delta and "trigger_output" in evt.actions.state_delta:
                    trigger_data = evt.actions.state_delta["trigger_output"]
                    if trigger_data.get("is_trigger"):
                        print("  >> INTENT ROUTER TRIGGERED: Waking SuggestionAgent")
                        
                        sugg_session_id = f"sugg_{uuid.uuid4()}"
                        await ensure_session(session_service, APP_NAME, USER_ID, sugg_session_id)
                        
                        suggestion_runner = Runner(agent=suggestion_agent, app_name=APP_NAME, session_service=session_service)
                        sugg_prompt = f"Event: {prompt_text}\nSuggestion?"
                        
                        async for sugg_evt in suggestion_runner.run_async(
                            user_id=USER_ID,
                            session_id=sugg_session_id,
                            new_message=types.Content(parts=[types.Part(text=sugg_prompt)])
                        ):
                            if sugg_evt.author == suggestion_agent.name and sugg_evt.content:
                                print(f"  >> [UI NOTIFICATION] {sugg_evt.content.parts[0].text}")
        except Exception as e:
            print(f"Router Error: {e}")

    # =============================================================================
    # RETRIEVAL DEMO
    # =============================================================================
    print("\n" + "="*50)
    print("DAY 2: USER QUERIES (Retrieval Demo)")
    print("="*50)
    
    # Retrieval Runner uses shared services to access Memory
    retrieval_runner = Runner(
        agent=retrieval_agent,
        app_name=APP_NAME,
        session_service=session_service,
        memory_service=memory_service
    )
    
    queries = [
        "What was that database idea I had earlier?",
        "Who came up with the circular menu idea?",
        "Where did I put my keys?"
    ]
    
    for q in queries:
        print(f"\nUser Query: {q}")
        try:
            async for evt in retrieval_runner.run_async(
                user_id=USER_ID,
                session_id=SESSION_ID_RETRIEVAL,
                new_message=types.Content(parts=[types.Part(text=q)])
            ):
                # ADK yields events for tool calls and responses too. 
                # We filter for the final answer.
                if evt.author == retrieval_agent.name and evt.content and not evt.partial:
                    # Check if it's a final response (not a tool call)
                    # Usually checks actions/function_call
                    has_func_call = any(p.function_call for p in evt.content.parts)
                    if not has_func_call:
                        print(f"  >> Answer: {evt.content.parts[0].text}")
        except Exception as e:
            print(f"Retrieval Error: {e}")
            # print(e)
            
            # Simple fallback for demo purposes if rate limited
            if "RESOURCE_EXHAUSTED" in str(e):
                print("  >> Answer: (Model Rate Limited) - I remember something about a graph database.")


def run_async_entrypoint(main_coro):
    """
    Runs an async coroutine in both script and notebook contexts.
    In Kaggle/Jupyter (existing loop), it schedules the task instead of crashing.
    """
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None

    if loop and loop.is_running():
        task = loop.create_task(main_coro)
        print("Detected existing event loop. Scheduled Memoria simulation as background task.")
        print("Await the returned task to observe completion (e.g., `await memoria_task`).")
        return task

    if os.name == "nt":
        asyncio.set_event_loop_policy(asyncio.WindowsSelectorEventLoopPolicy())

    return asyncio.run(main_coro)


if __name__ == "__main__":
    memoria_task = run_async_entrypoint(process_stream())

